import 'dart:io';

import 'package:yaml/yaml.dart';

/// Thrown for any invalid catalog input.
class EventCatalogException implements Exception {
  EventCatalogException(this.message);
  final String message;
  @override
  String toString() => 'EventCatalogException: $message';
}

const _header = '''
// SPDX-License-Identifier: GPL-3.0-or-later

// GENERATED by packages/observability/tool/generate_events.dart from
// packages/observability/events/*.yaml. DO NOT EDIT BY HAND.
// Regenerate: dart run packages/observability/tool/generate_events.dart
''';

final _snake = RegExp(r'^[a-z][a-z0-9]*(_[a-z0-9]+)*$');
final _pascal = RegExp(r'^[A-Z][A-Za-z0-9]*$');

/// The prefix every event name of a YAML file must start with: the file stem,
/// except where a shorter established word is used. A new area registers its
/// prefix here; an unregistered file defaults to its stem.
const _prefixOverrides = {'polling': 'poll'};

String _prefixFor(String file) {
  final base = file.split('/').last;
  final stem = base.endsWith('.yaml')
      ? base.substring(0, base.length - '.yaml'.length)
      : base;
  return _prefixOverrides[stem] ?? stem;
}

String _camel(String snake) {
  final parts = snake.split('_');
  return parts.first +
      parts
          .skip(1)
          .map((p) => p.isEmpty ? p : p[0].toUpperCase() + p.substring(1))
          .join();
}

String _pascalOf(String snake) {
  final c = _camel(snake);
  return c[0].toUpperCase() + c.substring(1);
}

class _Enum {
  _Enum(this.name);
  final String name;
  String? dart;
  final List<String> values = [];
}

class _Param {
  _Param(this.name, this.type, {required this.optional});
  final String name;
  final String type;
  final bool optional;
}

class _Event {
  _Event(this.name, this.description, this.params);
  final String name;
  final String description;
  final List<_Param> params;
}

/// Generates the catalog source from [yamlByFile] (file name -> YAML text).
///
/// Files are processed in sorted file-name order, so output is deterministic.
String generateCatalog(Map<String, String> yamlByFile) {
  final enums = <String, _Enum>{};
  final events = <String, _Event>{};

  for (final file in yamlByFile.keys.toList()..sort()) {
    final Object? doc;
    try {
      doc = loadYaml(yamlByFile[file]!);
    } on YamlException catch (e) {
      throw EventCatalogException('$file: invalid YAML (${e.message})');
    }
    if (doc == null) continue;
    if (doc is! Map) throw EventCatalogException('$file: expected a map');
    final enumDecls = doc['enums'] ?? const {};
    if (enumDecls is! Map) {
      throw EventCatalogException('$file: enums must be a map');
    }
    for (final entry in enumDecls.entries) {
      _readEnum(file, entry.key, entry.value, enums);
    }
  }
  for (final file in yamlByFile.keys.toList()..sort()) {
    final doc = loadYaml(yamlByFile[file]!);
    if (doc is! Map) continue;
    final eventDecls = doc['events'] ?? const {};
    if (eventDecls is! Map) {
      throw EventCatalogException('$file: events must be a map');
    }
    for (final entry in eventDecls.entries) {
      _readEvent(file, entry.key, entry.value, enums, events);
    }
  }
  for (final e in enums.values) {
    if (e.dart == null) {
      throw EventCatalogException('enum ${e.name}: missing dart name');
    }
    if (e.values.isEmpty) {
      throw EventCatalogException('enum ${e.name}: no values');
    }
  }
  return _render(enums, events);
}

void _readEnum(
  String file,
  Object? key,
  Object? body,
  Map<String, _Enum> enums,
) {
  if (key is! String || !_snake.hasMatch(key)) {
    throw EventCatalogException('$file: bad enum name "$key"');
  }
  if (body is! Map) throw EventCatalogException('$file: enum $key not a map');
  final e = enums.putIfAbsent(key, () => _Enum(key));
  final dart = body['dart'];
  if (dart != null) {
    if (dart is! String || !_pascal.hasMatch(dart)) {
      throw EventCatalogException('$file: enum $key: bad dart name');
    }
    if (e.dart != null && e.dart != dart) {
      throw EventCatalogException('$file: enum $key: conflicting dart name');
    }
    e.dart = dart;
  }
  final values = body['values'];
  if (values is! List) {
    throw EventCatalogException('$file: enum $key: values must be a list');
  }
  for (final v in values) {
    if (v is! String || !_snake.hasMatch(v)) {
      throw EventCatalogException('$file: enum $key: bad value "$v"');
    }
    if (e.values.contains(v)) {
      throw EventCatalogException('$file: enum $key: duplicate value "$v"');
    }
    e.values.add(v);
  }
}

void _readEvent(
  String file,
  Object? key,
  Object? body,
  Map<String, _Enum> enums,
  Map<String, _Event> events,
) {
  if (key is! String || !_snake.hasMatch(key)) {
    throw EventCatalogException('$file: bad event name "$key"');
  }
  final prefix = _prefixFor(file);
  if (!key.startsWith('${prefix}_')) {
    throw EventCatalogException(
      '$file: event "$key" must start with "${prefix}_" (the feature prefix '
      'of this file)',
    );
  }
  if (events.containsKey(key)) {
    throw EventCatalogException('$file: duplicate event "$key"');
  }
  if (body is! Map) throw EventCatalogException('$file: event $key not a map');
  final description = body['description'];
  if (description is! String || description.trim().isEmpty) {
    throw EventCatalogException('$file: event $key: description required');
  }
  final paramDecls = body['params'] ?? const {};
  if (paramDecls is! Map) {
    throw EventCatalogException('$file: event $key: params must be a map');
  }
  final params = <_Param>[];
  for (final p in paramDecls.entries) {
    final name = p.key;
    if (name is! String || !_snake.hasMatch(name)) {
      throw EventCatalogException('$file: event $key: bad param "$name"');
    }
    final spec = p.value;
    if (spec is! Map || spec['type'] is! String) {
      throw EventCatalogException('$file: $key.$name: type required');
    }
    final type = spec['type'] as String;
    if (type != 'int' && type != 'bool' && !enums.containsKey(type)) {
      throw EventCatalogException(
        '$file: $key.$name: type "$type" is not allowed '
        '(only int, bool or a declared enum; no free text)',
      );
    }
    final optional = spec['optional'] ?? false;
    if (optional is! bool) {
      throw EventCatalogException('$file: $key.$name: optional must be bool');
    }
    params.add(_Param(name, type, optional: optional));
  }
  events[key] = _Event(key, description.trim(), params);
}

String _render(Map<String, _Enum> enums, Map<String, _Event> events) {
  final b = StringBuffer(_header);
  for (final e in enums.values) {
    final dart = e.dart!;
    b
      ..writeln()
      ..writeln('enum $dart {');
    for (var i = 0; i < e.values.length; i++) {
      final v = e.values[i];
      b.writeln("  ${_camel(v)}('$v')${i == e.values.length - 1 ? ';' : ','}");
    }
    b
      ..writeln()
      ..writeln('  const $dart(this.code);')
      ..writeln()
      ..writeln('  /// Stable wire value.')
      ..writeln('  final String code;')
      ..writeln()
      ..writeln('  /// The value with wire [code], or null.')
      ..writeln('  static $dart? fromCode(String code) {')
      ..writeln('    for (final v in values) {')
      ..writeln('      if (v.code == code) return v;')
      ..writeln('    }')
      ..writeln('    return null;')
      ..writeln('  }')
      ..writeln('}');
  }
  b
    ..writeln()
    ..writeln('/// A catalogued analytics event. Parameters are closed values')
    ..writeln('/// (enums, ints, bools) only.')
    ..writeln('sealed class AppEvent {')
    ..writeln('  const AppEvent();')
    ..writeln()
    ..writeln('  /// Stable snake_case event name.')
    ..writeln('  String get name;')
    ..writeln()
    ..writeln('  /// Wire parameters (absent optionals are omitted).')
    ..writeln('  Map<String, Object> get parameters;')
    ..writeln('}');
  for (final ev in events.values) {
    final cls = '${_pascalOf(ev.name)}Event';
    String typeOf(_Param p) {
      final base = switch (p.type) {
        'int' => 'int',
        'bool' => 'bool',
        _ => enums[p.type]!.dart!,
      };
      return p.optional ? '$base?' : base;
    }

    b
      ..writeln()
      ..writeln('/// ${ev.description}')
      ..writeln('final class $cls extends AppEvent {');
    if (ev.params.isEmpty) {
      b.writeln('  const $cls();');
    } else {
      b.writeln('  const $cls({');
      for (final p in ev.params) {
        b.writeln(
          '    ${p.optional ? '' : 'required '}this.${_camel(p.name)},',
        );
      }
      b.writeln('  });');
    }
    for (final p in ev.params) {
      b
        ..writeln()
        ..writeln('  final ${typeOf(p)} ${_camel(p.name)};');
    }
    b
      ..writeln()
      ..writeln('  @override')
      ..writeln("  String get name => '${ev.name}';")
      ..writeln()
      ..writeln('  @override')
      ..writeln('  Map<String, Object> get parameters => {');
    for (final p in ev.params) {
      final f = _camel(p.name);
      final ref = p.optional ? '$f!' : f;
      final value = switch (p.type) {
        'int' || 'bool' => ref,
        _ => '$ref.code',
      };
      final guard = p.optional ? 'if ($f != null) ' : '';
      b.writeln("    $guard'${p.name}': $value,");
    }
    b.writeln('  };');
    b.writeln('}');
  }
  return b.toString();
}

/// Runs `dart format` over [source] so the committed file is formatter-clean
/// (CI checks formatting) and drift checks compare like with like.
String formatWithDart(String source, {required String scratchDir}) {
  final dir = Directory(scratchDir)..createSync(recursive: true);
  final file = File('${dir.path}/catalog_format.dart')
    ..writeAsStringSync(source);
  final r = Process.runSync('dart', ['format', file.path]);
  if (r.exitCode != 0) {
    throw EventCatalogException('dart format failed: ${r.stderr}');
  }
  final out = file.readAsStringSync();
  file.deleteSync();
  return out;
}
